import{_ as e,c as r,o as i,ah as n}from"./chunks/framework.Dnh4IO1K.js";const b=JSON.parse('{"title":"11、【泰】 乾下坤上","description":"溫公易說 - 11、【泰】 乾下坤上","frontmatter":{"title":"11、【泰】 乾下坤上","description":"溫公易說 - 11、【泰】 乾下坤上"},"headers":[],"relativePath":"classics/wengong/012.md","filePath":"classics/wengong/012.md"}'),l={name:"classics/wengong/012.md"};function t(h,a,s,o,d,c){return i(),r("div",null,[...a[0]||(a[0]=[n('<h1 id="_11、【泰】-乾下坤上" tabindex="-1">11、【泰】 乾下坤上 <a class="header-anchor" href="#_11、【泰】-乾下坤上" aria-label="Permalink to “11、【泰】 乾下坤上”">​</a></h1><h3 id="彖曰-泰-小往大來-吉亨-則是天地交而萬物通也-上下交而其志同也。內陽而外陰-內健而外順-內君子而外小人。君子道長-小人道消也。" tabindex="-1">彖曰：泰，小往大來，吉亨，則是天地交而萬物通也，上下交而其志同也。內陽而外陰，內健而外順，內君子而外小人。君子道長，小人道消也。 <a class="header-anchor" href="#彖曰-泰-小往大來-吉亨-則是天地交而萬物通也-上下交而其志同也。內陽而外陰-內健而外順-內君子而外小人。君子道長-小人道消也。" aria-label="Permalink to “彖曰：泰，小往大來，吉亨，則是天地交而萬物通也，上下交而其志同也。內陽而外陰，內健而外順，內君子而外小人。君子道長，小人道消也。”">​</a></h3><h3 id="象曰-天地交-泰。後以財成天地之道-輔相天地之宜-以左右民。" tabindex="-1">象曰：天地交，泰。後以財成天地之道，輔相天地之宜，以左右民。 <a class="header-anchor" href="#象曰-天地交-泰。後以財成天地之道-輔相天地之宜-以左右民。" aria-label="Permalink to “象曰：天地交，泰。後以財成天地之道，輔相天地之宜，以左右民。”">​</a></h3><p>象曰後以財成天地之道，輔相天地之宜，何也？夫萬物生之者天也，成之者地也。天地能生成之而不能治也，君者所以治人而成天地之功也。非後則天地何以得通乎？太曰：天之所貴曰生，物之所尊曰人，人之大倫曰治。治之所因曰闢，崇天普地，分群偶物，使不失其統者，莫若乎闢。天闢乎上，地闢乎下，君闢乎中，此之謂也。</p><h3 id="初九-拔茅茹-以其彚-徵吉-象曰-拔茅徵吉-志在外也。" tabindex="-1">初九：拔茅茹，以其彚，徵吉 象曰：拔茅徵吉，志在外也。 <a class="header-anchor" href="#初九-拔茅茹-以其彚-徵吉-象曰-拔茅徵吉-志在外也。" aria-label="Permalink to “初九：拔茅茹，以其彚，徵吉 象曰：拔茅徵吉，志在外也。”">​</a></h3><h3 id="九二-包荒-用馮河-不遐遺-朋亡得-尚於中行-象曰-包荒得尚於中行-以光大也。" tabindex="-1">九二：包荒，用馮河，不遐遺，朋亡得，尚於中行 象曰：包荒得尚於中行，以光大也。 <a class="header-anchor" href="#九二-包荒-用馮河-不遐遺-朋亡得-尚於中行-象曰-包荒得尚於中行-以光大也。" aria-label="Permalink to “九二：包荒，用馮河，不遐遺，朋亡得，尚於中行 象曰：包荒得尚於中行，以光大也。”">​</a></h3><h3 id="九三-無平不陂-無往不復-艱貞無咎-勿恤其孚-於食有福-象曰-無往不復-天地際也。" tabindex="-1">九三：無平不陂，無往不復，艱貞無咎，勿恤其孚，於食有福 象曰：無往不復，天地際也。 <a class="header-anchor" href="#九三-無平不陂-無往不復-艱貞無咎-勿恤其孚-於食有福-象曰-無往不復-天地際也。" aria-label="Permalink to “九三：無平不陂，無往不復，艱貞無咎，勿恤其孚，於食有福 象曰：無往不復，天地際也。”">​</a></h3><p>物極則反，天地之常也。是故治者亂之原也，通者塞之端也。三居天地之際，剛德將退，柔德將進，故曰無平不陂，無往不復。君子於是時也，何為而可哉？必也執節守道而獨行其志乎？故曰艱貞無咎，君子之道也。患志之不篤，不患人之不信。譬如農夫，是穮是蔉，雖有饑饉，必有豐年。故勿恤其孚，君子之幹祿也。修其性，俟其命而已矣，然後能永享安榮也。故曰於食有福。《詩》雲：愷悌君子，求福不回，此之謂也。</p><h3 id="六四-翩翩-不富-以其鄰-不戒以孚-象曰-翩翩不富-皆失實也。不戒以孚-中心願也。" tabindex="-1">六四：翩翩，不富，以其鄰，不戒以孚 象曰：翩翩不富，皆失實也。不戒以孚，中心願也。 <a class="header-anchor" href="#六四-翩翩-不富-以其鄰-不戒以孚-象曰-翩翩不富-皆失實也。不戒以孚-中心願也。" aria-label="Permalink to “六四：翩翩，不富，以其鄰，不戒以孚 象曰：翩翩不富，皆失實也。不戒以孚，中心願也。”">​</a></h3><h3 id="六五-帝乙歸妹-以祉-元吉-象曰-以祉元吉-中以行願也。" tabindex="-1">六五：帝乙歸妹，以祉，元吉 象曰：以祉元吉，中以行願也。 <a class="header-anchor" href="#六五-帝乙歸妹-以祉-元吉-象曰-以祉元吉-中以行願也。" aria-label="Permalink to “六五：帝乙歸妹，以祉，元吉 象曰：以祉元吉，中以行願也。”">​</a></h3><h3 id="上六-城復於隍-勿用師-自邑告命-貞吝-象曰-城復於隍-其命亂也。" tabindex="-1">上六：城復於隍，勿用師，自邑告命，貞吝 象曰：城復於隍，其命亂也。 <a class="header-anchor" href="#上六-城復於隍-勿用師-自邑告命-貞吝-象曰-城復於隍-其命亂也。" aria-label="Permalink to “上六：城復於隍，勿用師，自邑告命，貞吝 象曰：城復於隍，其命亂也。”">​</a></h3>',11)])])}const m=e(l,[["render",t]]);export{b as __pageData,m as default};
